{
  "name": "罗德与施瓦茨测试仪器",
  "name_en": "Rohde & Schwarz Test Instrument",
  "manufacturer": "Rohde & Schwarz",
  "description": "这是一类支持 VISA/SCPI 远程控制的罗德与施瓦茨电子测试仪器，可通过 TCP/IP 等接口接入实验室自动化系统。常见用途包括远程参数设置、触发测量、读取波形或测量结果，以及进行自动化测试与数据采集。",
  "description_en": "This refers to a Rohde & Schwarz electronic test instrument that supports remote control through VISA/SCPI, typically connected over interfaces such as TCP/IP. In laboratories, such instruments are used for automated setup, triggering measurements, reading waveforms or measurement results, and collecting data in test workflows.",
  "tag_hints": [
    "Rohde & Schwarz",
    "VISA control",
    "SCPI",
    "electronic test instrumentation",
    "remote measurement automation",
    "TCP/IP instrument control"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭与仪器的 VISA 通信会话。",
      "description_en": "Close the VISA communication session to the instrument."
    },
    {
      "action_name": "auto-open",
      "description": "打开与指定资源地址仪器的 VISA 通信会话。",
      "description_en": "Open a VISA communication session to the instrument at the specified resource address."
    },
    {
      "action_name": "auto-query",
      "description": "向仪器发送 SCPI 查询并读取返回结果。",
      "description_en": "Send an SCPI query to the instrument and read back the response."
    },
    {
      "action_name": "auto-read_raw",
      "description": "读取仪器返回的原始字节或二进制数据。",
      "description_en": "Read raw byte or binary data returned by the instrument."
    },
    {
      "action_name": "auto-reslist",
      "description": "列出当前系统中可访问的 VISA 仪器资源。",
      "description_en": "List the VISA instrument resources currently accessible on the system."
    },
    {
      "action_name": "auto-timeout",
      "description": "设置仪器通信会话的超时时间。",
      "description_en": "Set the timeout for the instrument communication session."
    },
    {
      "action_name": "auto-write",
      "description": "向仪器发送 SCPI 命令。",
      "description_en": "Send an SCPI command to the instrument."
    },
    {
      "action_name": "auto-write_raw",
      "description": "向仪器发送原始字节或二进制数据。",
      "description_en": "Send raw byte or binary data to the instrument."
    }
  ]
}

